FUNCTION_BLOCK FB_S12
VAR_INPUT
    EStop_NC : BOOL;
    ResetBtn : BOOL;
    StartBtn : BOOL;
    DoorClosed : BOOL;
END_VAR
VAR_OUTPUT
    MachineRun : BOOL := FALSE;
    ShiftCount : UINT := UINT#0;
    AlarmLamp : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    ResetConfirmed : BOOL := FALSE;
    ResetBtnLast : BOOL := FALSE;
    StartBtnLast : BOOL := FALSE;
    ResetRise : BOOL := FALSE;
    StartRise : BOOL := FALSE;
    RunScans : UINT := UINT#0;
END_VAR

(*
    待审语义冲突：
    C10 要求前两个扫描输出 AlarmLamp = FALSE，
    但需求 1 要求任何急停扫描立即 AlarmLamp = TRUE。
    C10 的第二扫描禁止运行，也可能与首扫描复位、
    次扫描启动的合法顺序冲突。
    本实现保留声明初值，扫描逻辑优先执行急停安全要求及
    门关、复位、后续启动流程，不声称满足冲突的 C10。

    每次调用累计一个 20 ms 运行扫描；3000 个运行扫描为一分钟。
    停机时保留不足一分钟的累计量，不清零 ShiftCount。
    UINT 达到上限时饱和，避免回绕；上限后的统计行为待需求确认。
    本源码未声称经过编译或逐周期测试验证。
*)

ResetRise := ResetBtn AND NOT ResetBtnLast;
StartRise := StartBtn AND NOT StartBtnLast;

(* 所有扫描均更新历史值，急停期间的按钮边沿不能留到解除后使用。 *)
ResetBtnLast := ResetBtn;
StartBtnLast := StartBtn;

IF NOT EStop_NC THEN
    MachineRun := FALSE;
    ResetConfirmed := FALSE;
    AlarmLamp := TRUE;
    Status := WORD#16#8B01;

ELSIF NOT DoorClosed THEN
    MachineRun := FALSE;
    ResetConfirmed := FALSE;
    AlarmLamp := FALSE;
    Status := WORD#16#8B03;

ELSE
    AlarmLamp := FALSE;

    IF NOT ResetConfirmed THEN
        MachineRun := FALSE;

        IF ResetRise THEN
            ResetConfirmed := TRUE;
        END_IF;
    ELSE
        (* 与复位分属不同扫描；同时按下复位和启动不能直接启动。 *)
        IF StartRise THEN
            MachineRun := TRUE;
        END_IF;
    END_IF;

    IF ResetConfirmed THEN
        Status := WORD#16#0000;
    ELSE
        Status := WORD#16#8B02;
    END_IF;
END_IF;

(* 安全判定在统计之前执行，急停当扫描不累计运行时间。 *)
IF MachineRun THEN
    IF RunScans >= UINT#2999 THEN
        RunScans := UINT#0;
        IF ShiftCount < UINT#65535 THEN
            ShiftCount := ShiftCount + UINT#1;
        END_IF;
    ELSE
        RunScans := RunScans + UINT#1;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
